//! `SwitchOverStringVisitor`: restore `switch` over a string from the two switches (or the hash
//! compare `if` chain and the switch) generated by the compiler.

use std::collections::HashMap;

use jadx_input_api::ConstValue;

use crate::model::bitset::java_hash_map_order_compute_cap;
use crate::model::cfg::MethodCfg;
use crate::model::insn::{
    iflag, BlockId, IfOp, IndexValue, InsnArg, InsnId, InsnKind, InsnType, InvokeType, RegisterArg,
};
use crate::model::region::{CaseInfo, CaseKey, Container, RegionId, RegionKind};
use crate::passes::constructor::MethodEnv;
use crate::passes::insn_utils::{replace_insn_by_ref, same_reg_and_svar, Remover};
use crate::passes::mod_visitor::const_literal_by_arg;
use crate::passes::regions::maker::Res;
use crate::passes::regions::traversal::traverse_iterative;
use crate::passes::regions::utils::{
    collect_blocks, container_insns, get_block_container, get_first_block_node, get_next_container,
    last_insn, next_block,
};

const DEFAULT_NUM_VALUE: i32 = -1;

#[derive(Clone, Copy, PartialEq, Eq)]
enum SwitchStringType {
    Single,
    IfSwitch,
    Double,
}

/// A string and the number (or code block) of its case.
struct CaseData {
    /// `None` is the default case key
    str_value: Option<Vec<u16>>,
    code: Option<BlockId>,
    code_num: Option<i32>,
}

struct SwitchData {
    ty: SwitchStringType,
    part1: RegionId,
    part2: Option<RegionId>,
    cases: Vec<CaseData>,
    new_cases: Vec<CaseInfo>,
    num_arg: Option<RegisterArg>,
    str_arg: RegisterArg,
    hashcode_invoke: InsnId,
}

pub fn switch_over_string(cfg: &mut MethodCfg, env: &MethodEnv) -> Res<()> {
    if !cfg.has_switch {
        return Ok(());
    }
    traverse_iterative(cfg, &mut |cfg, region| {
        if matches!(
            cfg.regions.arena[region].kind,
            RegionKind::Switch { .. } | RegionKind::If { .. }
        ) {
            return Ok(restore_switch_over_string(cfg, env, region));
        }
        Ok(false)
    })
}

fn restore_switch_over_string(cfg: &mut MethodCfg, env: &MethodEnv, part1: RegionId) -> bool {
    match try_restore(cfg, env, part1) {
        Ok(r) => r,
        Err(_) => {
            cfg.warnings.push(
                "Failed to restore switch over string. Please report as a decompilation issue"
                    .to_string(),
            );
            false
        }
    }
}

fn reg_of(cfg: &MethodCfg, insn: InsnId, k: usize) -> Option<RegisterArg> {
    match cfg.insn(insn).args.get(k) {
        Some(InsnArg::Register(r)) => Some(r.clone()),
        _ => None,
    }
}

fn try_restore(cfg: &mut MethodCfg, env: &MethodEnv, part1: RegionId) -> Result<bool, String> {
    let first_block = get_first_block_node(cfg, Container::Region(part1));
    let str_hash_insn = first_block.and_then(|b| last_insn(cfg, b));
    let hashcode_inv = match str_hash_insn {
        Some(i) => {
            let arg = cfg
                .insn(i)
                .args
                .first()
                .ok_or_else(|| "no arguments".to_string())?
                .clone();
            get_str_hashcode_invoke_insn(cfg, &arg)
        }
        None => None,
    };
    let str_arg = match hashcode_inv {
        Some(inv) => instance_arg(cfg, inv),
        None => None,
    };
    let (Some(hashcode_inv), Some(str_arg)) = (hashcode_inv, str_arg) else {
        return Ok(false);
    };

    let mut data = SwitchData {
        ty: SwitchStringType::Double,
        part1,
        part2: None,
        cases: Vec::new(),
        new_cases: Vec::new(),
        num_arg: None,
        str_arg,
        hashcode_invoke: hashcode_inv,
    };

    let next_container = get_next_container(cfg, part1);
    let is_part1_switch = matches!(cfg.regions.arena[part1].kind, RegionKind::Switch { .. });
    let part2 = match next_container {
        Some(Container::Region(r))
            if matches!(cfg.regions.arena[r].kind, RegionKind::Switch { .. }) =>
        {
            Some(r)
        }
        _ => None,
    };
    if let Some(part2) = part2 {
        let RegionKind::Switch { header, .. } = &cfg.regions.arena[part2].kind else {
            return Ok(false);
        };
        let Some(sw) = last_insn_with_type(cfg, *header, InsnType::Switch) else {
            return Ok(false);
        };
        let Some(num_arg) = reg_of(cfg, sw, 0) else {
            return Ok(false);
        };
        data.ty = if is_part1_switch {
            SwitchStringType::Double
        } else {
            SwitchStringType::IfSwitch
        };
        data.part2 = Some(part2);
        data.num_arg = Some(num_arg);
    } else if is_part1_switch {
        data.ty = SwitchStringType::Single;
    } else {
        return Ok(false);
    }

    if !collect_part1_region_cases(cfg, env, &mut data)? {
        return Ok(false);
    }
    if !prepare_merged_switch_cases(cfg, &mut data)? || !replace_with_merged_switch(cfg, &data)? {
        cfg.warnings.push(
            "Failed to restore switch over string. Please report as a decompilation issue"
                .to_string(),
        );
        return Ok(false);
    }
    Ok(true)
}

fn last_insn_with_type(cfg: &MethodCfg, block: BlockId, ty: InsnType) -> Option<InsnId> {
    last_insn(cfg, block).filter(|i| cfg.insn(*i).ty == ty)
}

fn instance_arg(cfg: &MethodCfg, invoke: InsnId) -> Option<RegisterArg> {
    let n = cfg.insn(invoke);
    let InsnKind::Invoke { invoke_type, .. } = &n.kind else {
        return None;
    };
    if *invoke_type != InvokeType::Static && !n.args.is_empty() {
        return reg_of(cfg, invoke, 0);
    }
    None
}

fn raw_full_id(cfg: &MethodCfg, insn: InsnId) -> Option<String> {
    let InsnKind::Invoke { mth, .. } = &cfg.insn(insn).kind else {
        return None;
    };
    Some(format!("{}.{}", mth.decl_class.raw_name(), mth.short_id()))
}

/// `RegisterArg.getAssignInsn`
fn assign_insn(cfg: &MethodCfg, r: &RegisterArg) -> Option<InsnId> {
    match cfg.svars[r.svar?].assign {
        crate::model::ssa::ArgRef::Result(p) => Some(p),
        _ => None,
    }
}

fn get_str_hashcode_invoke_insn(cfg: &MethodCfg, arg: &InsnArg) -> Option<InsnId> {
    let insn = match arg {
        InsnArg::Register(r) => assign_insn(cfg, r),
        InsnArg::Wrapped(w) => Some(w.insn),
        _ => None,
    }?;
    if cfg.insn(insn).ty == InsnType::Invoke
        && raw_full_id(cfg, insn).as_deref() == Some("java.lang.String.hashCode()I")
    {
        return Some(insn);
    }
    None
}

fn is_if_string_equals_insn(cfg: &MethodCfg, if_insn: Option<InsnId>) -> bool {
    let Some(i) = if_insn else {
        return false;
    };
    let n = cfg.insn(i);
    if n.ty == InsnType::If && n.args.len() == 2 {
        if let Some(InsnArg::Wrapped(w)) = n.args.first() {
            return cfg.insn(w.insn).ty == InsnType::Invoke
                && raw_full_id(cfg, w.insn).as_deref()
                    == Some("java.lang.String.equals(Ljava/lang/Object;)Z");
        }
    }
    false
}

fn get_only_one_insn_block(cfg: &MethodCfg, mut b: Option<BlockId>) -> Option<BlockId> {
    while let Some(blk) = b {
        let size = cfg.block(blk).insns.len();
        if size == 0 {
            b = next_block(cfg, blk);
            continue;
        }
        return if size == 1 { Some(blk) } else { None };
    }
    None
}

fn if_blocks(cfg: &MethodCfg, insn: InsnId) -> (Option<BlockId>, Option<BlockId>, IfOp) {
    match &cfg.insn(insn).kind {
        InsnKind::If {
            op,
            then_block,
            else_block,
            ..
        } => (*then_block, *else_block, *op),
        _ => (None, None, IfOp::Eq),
    }
}

/// `InsnUtils.getConstValueByArg` for a string value.
fn const_string_by_arg(cfg: &MethodCfg, env: &MethodEnv, arg: &InsnArg) -> Option<Vec<u16>> {
    match arg {
        InsnArg::Register(r) => {
            let assign = cfg.svars[r.svar?].assign;
            let crate::model::ssa::ArgRef::Result(p) = assign else {
                return None;
            };
            let a = cfg.insn(p);
            if a.ty == InsnType::Move {
                return const_string_by_arg(cfg, env, a.args.first()?);
            }
            const_string_by_insn(cfg, env, p)
        }
        InsnArg::Wrapped(w) => const_string_by_insn(cfg, env, w.insn),
        _ => None,
    }
}

fn const_string_by_insn(cfg: &MethodCfg, env: &MethodEnv, insn: InsnId) -> Option<Vec<u16>> {
    let n = cfg.insn(insn);
    match (&n.ty, &n.kind) {
        (InsnType::ConstStr, InsnKind::ConstStr(s)) => Some(s.clone()),
        (InsnType::Sget, InsnKind::Index(IndexValue::Field(f))) => {
            match env.root.resolve_field(f)?.const_value.as_ref()? {
                ConstValue::Str(s) => Some(s.clone()),
                _ => None,
            }
        }
        _ => None,
    }
}

fn java_hash(units: &[u16]) -> i32 {
    units
        .iter()
        .fold(0i32, |h, c| h.wrapping_mul(31).wrapping_add(i32::from(*c)))
}

/// `RegisterArg.sameCodeVar`: `Err` stands for the `NullPointerException` of a missing argument.
fn same_code_var(
    cfg: &MethodCfg,
    a: &RegisterArg,
    b: Option<&RegisterArg>,
) -> Result<bool, String> {
    let b = b.ok_or_else(|| "null register".to_string())?;
    let cv = |r: &RegisterArg| -> Result<_, String> {
        let v = r.svar.ok_or_else(|| "no ssa var".to_string())?;
        Ok(cfg.svars[v].code_var)
    };
    Ok(cv(a)? == cv(b)?)
}

fn extract_const_number(
    cfg: &MethodCfg,
    env: &MethodEnv,
    data: &SwitchData,
    num_insn: Option<InsnId>,
) -> Result<Option<i32>, String> {
    let Some(num_insn) = num_insn else {
        return Ok(None);
    };
    let n = cfg.insn(num_insn);
    if n.args.len() != 1 {
        return Ok(None);
    }
    if let Some(lit) = const_literal_by_arg(cfg, env, &n.args[0]) {
        if let Some(num_arg) = &data.num_arg {
            if same_code_var(cfg, num_arg, n.result.as_ref())? {
                return Ok(Some(lit as i32));
            }
        }
    }
    Ok(None)
}

fn collect_part1_region_cases(
    cfg: &MethodCfg,
    env: &MethodEnv,
    data: &mut SwitchData,
) -> Result<bool, String> {
    // a map of hashcode keys and case blocks (insertion ordered)
    let mut hash_cases: Vec<(i32, BlockId)> = Vec::new();
    let mut put = |key: i32, block: BlockId| {
        if let Some(e) = hash_cases.iter_mut().find(|e| e.0 == key) {
            e.1 = block;
        } else {
            hash_cases.push((key, block));
        }
    };
    if data.ty == SwitchStringType::IfSwitch {
        let RegionKind::If { cond_blocks, .. } = &cfg.regions.arena[data.part1].kind else {
            return Ok(false);
        };
        let part2 = data.part2.ok_or_else(|| "no part2".to_string())?;
        let RegionKind::Switch {
            header: part2_header,
            ..
        } = &cfg.regions.arena[part2].kind
        else {
            return Ok(false);
        };
        let part2_header = *part2_header;
        let mut str_hash_arg: Option<RegisterArg> = None;
        let if_start_block = *cond_blocks
            .first()
            .ok_or_else(|| "no condition blocks".to_string())?;
        let mut hash_cmp_block = get_only_one_insn_block(cfg, Some(if_start_block));
        loop {
            let if_node = hash_cmp_block.and_then(|b| last_insn_with_type(cfg, b, InsnType::If));
            let Some(if_node) = if_node else {
                return Ok(false);
            };
            let (then_b, else_b, op) = if_blocks(cfg, if_node);
            if op != IfOp::Ne && op != IfOp::Eq {
                return Ok(false);
            }
            let is_ne = op == IfOp::Ne;
            let then_block = get_only_one_insn_block(cfg, if is_ne { else_b } else { then_b });
            let else_block = get_only_one_insn_block(cfg, if is_ne { then_b } else { else_b });
            let n = cfg.insn(if_node);
            let (Some(then_block), Some(else_block)) = (then_block, else_block) else {
                return Ok(false);
            };
            let (Some(InsnArg::Register(tmp_hash_arg)), Some(InsnArg::Literal(lit))) =
                (n.args.first(), n.args.get(1))
            else {
                return Ok(false);
            };
            match &str_hash_arg {
                None => str_hash_arg = Some(tmp_hash_arg.clone()),
                Some(s) => {
                    if !same_code_var(cfg, s, Some(tmp_hash_arg))? {
                        return Ok(false);
                    }
                }
            }
            put(lit.literal as i32, then_block);
            hash_cmp_block = Some(else_block);
            // end of part1If: no further hash compare, next block is part2switch
            let fallback_num = extract_const_number(cfg, env, data, last_insn(cfg, else_block))?;
            let next = next_block(cfg, else_block);
            if else_block == part2_header
                || (fallback_num == Some(DEFAULT_NUM_VALUE) && next == Some(part2_header))
            {
                break;
            }
        }
    } else {
        let RegionKind::Switch { header, .. } = &cfg.regions.arena[data.part1].kind else {
            return Ok(false);
        };
        let sw = last_insn_with_type(cfg, *header, InsnType::Switch)
            .ok_or_else(|| "no switch insn".to_string())?;
        let InsnKind::Switch {
            data: Some(sd),
            target_blocks: Some(tb),
            ..
        } = &cfg.insn(sw).kind
        else {
            return Err("switch data".to_string());
        };
        for i in 0..sd.keys.len() {
            let Some(case_block) = get_only_one_insn_block(cfg, tb.get(i).copied()) else {
                return Ok(false);
            };
            put(sd.keys[i], case_block);
        }
    }

    // save to switchData
    data.cases = Vec::with_capacity(hash_cases.len());
    for (hashcode, case_block) in hash_cases {
        let mut if_str_equals = last_insn_with_type(cfg, case_block, InsnType::If);
        if !is_if_string_equals_insn(cfg, if_str_equals) {
            return Ok(false);
        }
        loop {
            let ifi = if_str_equals.expect("checked above");
            let n = cfg.insn(ifi);
            let Some(InsnArg::Wrapped(w)) = n.args.first() else {
                return Err("string equals insn".to_string());
            };
            let eq = cfg.insn(w.insn);
            let (Some(str_arg), Some(val_arg)) = (eq.args.first(), eq.args.get(1)) else {
                return Err("string equals args".to_string());
            };
            let str_value = const_string_by_arg(cfg, env, val_arg);
            let same_str =
                matches!(str_arg, InsnArg::Register(r) if same_reg_and_svar(&data.str_arg, r));
            let Some(str_value) = str_value.filter(|v| same_str && java_hash(v) == hashcode) else {
                return Ok(false);
            };
            let (then_b, else_b, op) = if_blocks(cfg, ifi);
            let arg1_true = matches!(n.args.get(1), Some(InsnArg::Literal(l))
                if l.literal == 1 && l.ty == crate::model::types::ArgType::boolean());
            let is_cmp_ne = (op == IfOp::Eq) != arg1_true;
            let then_block = if is_cmp_ne { else_b } else { then_b };
            let else_block = if is_cmp_ne { then_b } else { else_b };
            let mut num_value: Option<i32> = None;
            if matches!(
                data.ty,
                SwitchStringType::Double | SwitchStringType::IfSwitch
            ) {
                let one = get_only_one_insn_block(cfg, then_block);
                let num_insn = one.and_then(|b| last_insn(cfg, b));
                let num_arg = data
                    .num_arg
                    .as_ref()
                    .ok_or_else(|| "no num arg".to_string())?;
                if let Some(then_b) = then_block
                    .filter(|_| num_insn.is_none_or(|i| cfg.insn(i).ty == InsnType::Switch))
                {
                    // num is assigned before 1st region. find nearest assign
                    let mut idom = cfg.block(then_b).idom;
                    while let (Some(d), None) = (idom, num_value) {
                        for &insn in &cfg.block(d).insns {
                            num_value = extract_const_number(cfg, env, data, Some(insn))?;
                        }
                        idom = cfg.block(d).idom;
                    }
                    if num_value.is_none() {
                        return Ok(false);
                    }
                } else if let Some(ni) = num_insn {
                    if same_code_var(cfg, num_arg, cfg.insn(ni).result.as_ref())? {
                        num_value = extract_const_number(cfg, env, data, Some(ni))?;
                    } else {
                        return Ok(false);
                    }
                } else {
                    return Ok(false);
                }
            }
            // store str and num assign in switchData
            data.cases.push(CaseData {
                str_value: Some(str_value),
                code_num: num_value,
                code: then_block,
            });
            // there may be more string compare (same hashcode)
            let next_if_block = get_only_one_insn_block(cfg, else_block);
            if_str_equals = next_if_block.and_then(|b| last_insn_with_type(cfg, b, InsnType::If));
            if !is_if_string_equals_insn(cfg, if_str_equals) {
                break;
            }
        }
    }
    Ok(true)
}

fn key_text(units: &[u16]) -> String {
    String::from_utf16_lossy(units)
}

/// Create cases according to part2Region (part1Region if is SINGLE_SWITCH), replace keys with strings.
fn prepare_merged_switch_cases(cfg: &MethodCfg, data: &mut SwitchData) -> Result<bool, String> {
    let mut new_cases: Vec<CaseInfo> = Vec::new();
    if matches!(
        data.ty,
        SwitchStringType::Double | SwitchStringType::IfSwitch
    ) {
        // group by num
        let mut order: Vec<Option<i32>> = Vec::new();
        let mut cases_map: HashMap<Option<i32>, Vec<Vec<u16>>> = HashMap::new();
        for c in &data.cases {
            let list = cases_map.entry(c.code_num).or_insert_with(|| {
                order.push(c.code_num);
                Vec::new()
            });
            list.push(c.str_value.clone().unwrap_or_default());
        }
        let hashes: Vec<i32> = order.iter().map(|k| k.unwrap_or(0)).collect();
        let cap = data.cases.len().max(1).next_power_of_two();
        let hash_order: Vec<Option<i32>> = java_hash_map_order_compute_cap(&hashes, cap)
            .into_iter()
            .map(|i| order[i])
            .collect();
        let part2 = data.part2.ok_or_else(|| "no part2".to_string())?;
        let RegionKind::Switch { cases, .. } = &cfg.regions.arena[part2].kind else {
            return Ok(false);
        };
        for case_info in cases {
            let mut keys: Vec<CaseKey> = Vec::new();
            for key in &case_info.keys {
                match key {
                    CaseKey::Default => {
                        // last case. add all remaining strings
                        for k in &hash_order {
                            if let Some(strings) = cases_map.get(k) {
                                keys.extend(strings.iter().map(|s| CaseKey::Str(key_text(s))));
                            }
                        }
                        cases_map.clear();
                        keys.push(CaseKey::Default);
                    }
                    CaseKey::Int(i) => {
                        let strings = cases_map.remove(&Some(*i));
                        let Some(strings) = strings.filter(|s| !s.is_empty()) else {
                            return Ok(false);
                        };
                        keys.extend(strings.iter().map(|s| CaseKey::Str(key_text(s))));
                    }
                    CaseKey::Str(_) => return Err("unexpected string key".to_string()),
                }
            }
            new_cases.push(CaseInfo {
                keys,
                container: case_info.container,
            });
        }
    } else if data.ty == SwitchStringType::Single {
        let RegionKind::Switch { header, .. } = &cfg.regions.arena[data.part1].kind else {
            return Ok(false);
        };
        let sw = last_insn_with_type(cfg, *header, InsnType::Switch)
            .ok_or_else(|| "no switch insn".to_string())?;
        let InsnKind::Switch { def_block, .. } = &cfg.insn(sw).kind else {
            return Err("switch".to_string());
        };
        if let Some(def) = def_block {
            data.cases.push(CaseData {
                str_value: None,
                code_num: Some(DEFAULT_NUM_VALUE),
                code: Some(*def),
            });
        }
        let mut last: Option<Option<BlockId>> = None;
        for c in &data.cases {
            let key = match &c.str_value {
                Some(s) => CaseKey::Str(key_text(s)),
                None => CaseKey::Default,
            };
            if last == Some(c.code) && last.is_some() {
                new_cases
                    .last_mut()
                    .ok_or_else(|| "no case".to_string())?
                    .keys
                    .push(key);
            } else {
                let Some(code) = c.code else {
                    return Ok(false);
                };
                let Some(container) = get_block_container(cfg, Container::Region(data.part1), code)
                else {
                    return Ok(false);
                };
                new_cases.push(CaseInfo {
                    keys: vec![key],
                    container,
                });
            }
            last = Some(c.code);
        }
    }
    data.new_cases = new_cases;
    Ok(true)
}

/// Replace with new switch, remove original code.
fn replace_with_merged_switch(cfg: &mut MethodCfg, data: &SwitchData) -> Result<bool, String> {
    let part1 = data.part1;
    let part1_parent = cfg.regions.arena[part1]
        .parent
        .ok_or_else(|| "no parent".to_string())?;
    let mut kept_insns: Vec<InsnId> = Vec::new();
    let new_header = match data.ty {
        SwitchStringType::Double | SwitchStringType::Single => {
            let RegionKind::Switch { header, .. } = &cfg.regions.arena[part1].kind else {
                return Ok(false);
            };
            *header
        }
        SwitchStringType::IfSwitch => {
            let part2 = data.part2.ok_or_else(|| "no part2".to_string())?;
            let RegionKind::Switch { header, .. } = &cfg.regions.arena[part2].kind else {
                return Ok(false);
            };
            *header
        }
    };
    // use string arg directly in switch
    let sw_insn = last_insn_with_type(cfg, new_header, InsnType::Switch)
        .ok_or_else(|| "no switch insn".to_string())?;
    let new_sw = cfg.copy_without_result(sw_insn);
    let dup = InsnArg::Register(data.str_arg.clone());
    cfg.replace_arg(new_sw, 0, dup);
    replace_insn_by_ref(cfg, new_header, sw_insn, new_sw)?;
    if let Some(r) = cfg.regions.insn_region_ref.get(&sw_insn).copied() {
        cfg.regions.insn_region_ref.insert(new_sw, r);
    }
    kept_insns.push(new_sw);

    let new_region = cfg.regions.new_region(
        Some(part1_parent),
        RegionKind::Switch {
            header: new_header,
            cases: Vec::new(),
        },
    );
    for case_info in &data.new_cases {
        let container = case_info.container;
        let mut blocks = Vec::new();
        collect_blocks(cfg, container, &mut blocks);
        for b in blocks {
            kept_insns.extend(container_insns(cfg, b));
        }
        if let RegionKind::Switch { cases, .. } = &mut cfg.regions.arena[new_region].kind {
            cases.push(CaseInfo {
                keys: case_info.keys.clone(),
                container,
            });
        }
        cfg.regions.set_parent(container, Some(new_region));
    }
    if !cfg.regions.replace_sub_block(
        part1_parent,
        Container::Region(part1),
        Container::Region(new_region),
    ) {
        return Ok(false);
    }

    // remove original code
    if let Err(e) = remove_original_code(cfg, data, &kept_insns) {
        cfg.warnings.push(format!(
            "Failed to clean up code after switch over string restore: {e}"
        ));
    }
    Ok(true)
}

fn collect_insns(cfg: &MethodCfg, c: Container) -> Vec<InsnId> {
    let mut blocks = Vec::new();
    collect_blocks(cfg, c, &mut blocks);
    blocks
        .into_iter()
        .flat_map(|b| container_insns(cfg, b))
        .collect()
}

fn remove_original_code(
    cfg: &mut MethodCfg,
    data: &SwitchData,
    kept_insns: &[InsnId],
) -> Result<(), String> {
    let mut remove_insns = collect_insns(cfg, Container::Region(data.part1));
    if let Some(part2) = data.part2 {
        remove_insns.extend(collect_insns(cfg, Container::Region(part2)));
        if let Some(parent) = cfg.regions.arena[part2].parent {
            if matches!(
                cfg.regions.arena[parent].kind,
                RegionKind::Plain { .. } | RegionKind::Sync { .. }
            ) {
                cfg.regions
                    .plain_blocks_mut(parent)
                    .retain(|c| *c != Container::Region(part2));
            }
        }
    }
    remove_insns.retain(|i| !kept_insns.contains(i));
    for i in remove_insns {
        cfg.insns[i].flags |= iflag::REMOVE;
    }
    // may be assigned before 1st region
    if let Some(num_arg) = &data.num_arg {
        let var = num_arg.svar.ok_or_else(|| "no ssa var".to_string())?;
        let cv = cfg.svars[var]
            .code_var
            .ok_or_else(|| "no code var".to_string())?;
        for ssa_var in cfg.code_vars[cv].ssa_vars.clone() {
            if let Some(assign) = cfg.svar_assign_insn(ssa_var) {
                cfg.insns[assign].flags |= iflag::REMOVE;
            }
            for u in cfg.svars[ssa_var].uses.clone() {
                if let Some(p) = u.parent_insn() {
                    cfg.insns[p].flags |= iflag::REMOVE;
                }
            }
            cfg.remove_svar(ssa_var);
        }
    }
    remove_all_marked(cfg)?;
    cfg.remove_insn(data.hashcode_invoke)
}

/// `InsnRemover.removeAllMarked`
pub fn remove_all_marked(cfg: &mut MethodCfg) -> Result<(), String> {
    for block in cfg.blocks.clone() {
        let mut remover = Remover::default();
        for insn in cfg.block(block).insns.clone() {
            if cfg.insn(insn).contains_flag(iflag::REMOVE) {
                remover.add_without_unbind(insn);
            }
        }
        remover.perform(cfg, block)?;
    }
    Ok(())
}
